+		}
+	}
+	if len(s.exts) > maxGatewayExternals {
+		t.Fatalf("table holds %d gateways, bound %d", len(s.exts), maxGatewayExternals)
+	}
+	gw = "0101A8C0"
+	if n, _ := s.ReadLocal(); n.External.IsValid() {
+		t.Fatalf("an evicted gateway kept %v", n.External)
+	}
+}
